src = 'uncertified-zeros-v0.9-draft.md'
dst = 'uncertified-zeros-v0.9.1-draft.md'
shutil.copy(src, dst)
s = io.open(dst, encoding='utf-8').read()
n = 0
def rep(old, new):
    global s, n
    assert old in s, 'アンカー不在: ' + old[:50]
    assert s.count(old) == 1, 'アンカー非一意: ' + old[:50]
    s = s.replace(old, new); n += 1

